<template><AppShell><view class="page-heading"><text class="eyebrow">山河长卷 / CHRONICLES</text><text class="page-title">循着年代，走进人生</text><text class="muted">有明确日期的史料片段 · 保留每份来源的日期精度</text></view><view class="timeline-filters"><view class="person-picker"><text class="eyebrow">选择人物</text><picker :range="personOptions" range-key="name" :value="selected" @change="select"><view class="picker-button">{{personOptions[selected]?.name||'全部人物'}} <text>⌄</text></view></picker></view><view class="chips"><button v-for="s in stages" :key="s" :class="{active:stage===s}" @tap="stage=s">{{s}}</button></view><button class="text-button" @tap="list=!list">{{list?'长卷视图':'简洁列表'}} ⇄</button></view><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else><view class="list-summary"><text>{{items.length}} 个阅读片段</text><text>明确年份排序 · 不等同完整生平</text></view><view v-if="items.length" class="timeline-scroll" :class="{list}"><view v-for="(e,i) in items" :key="e.id" class="timeline-entry" :class="{alternate:i%2===1}"><view class="timeline-year"><text>{{e.sort_year}}</text><text class="timeline-dot"/></view><view class="timeline-card" @tap="go('event',{id:e.id})"><view class="card-date"><text>{{e.date_text}}</text><text>{{e.person_name}}</text></view><text class="timeline-title">{{e.title}}</text><text class="timeline-summary">{{e.summary}}</text><view class="card-foot"><text>{{e.stage}}</text><text>阅读片段 ↗</text></view></view></view></view><StatePanel v-else title="该阶段暂无确定日期片段" message="切换人物或阶段，其他资料仍可在事实与来源中阅读。"/></template></AppShell></template>
<script setup>
import {ref,watch} from 'vue';import {onShow,onShareAppMessage} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StatePanel from '../../components/StatePanel.vue';import {api} from '../../lib/api.js';import {go} from '../../lib/navigation.js'
const personOptions=ref([{id:'',name:'全部人物'}]),selected=ref(0),stage=ref('全部'),stages=['全部','早年求索','革命实践','时代风云','信念与传承'],list=ref(false),items=ref([]),loading=ref(true),error=ref('');let sequence=0
async function load(){const token=++sequence;loading.value=true;error.value='';try{const data=await api('timeline',{person_id:personOptions.value[selected.value]?.id||'',stage:stage.value==='全部'?'':stage.value,limit:100});if(token===sequence)items.value=data.items}catch(e){if(token===sequence)error.value=e.message}finally{if(token===sequence)loading.value=false}}
function select(e){selected.value=Number(e.detail.value)}
watch([selected,stage],load)
onShow(async()=>{try{if(personOptions.value.length===1){const data=await api('people',{limit:100});personOptions.value=[{id:'',name:'全部人物'},...data.items]}const target=uni.getStorageSync('yingji:timeline-person');if(target&&typeof target==='object'){uni.removeStorageSync('yingji:timeline-person');const found=personOptions.value.findIndex(p=>p.id===target.person_id);selected.value=found<0?0:found}await load()}catch(e){error.value=e.message;loading.value=false}})
onShareAppMessage(()=>({title:'英迹 · 山河长卷',path:'/pages/timeline/index'}))
</script>
